const reverse=Object.fromEntries(Object.entries(strings).map(([ar,en])=>[en,ar]));
let language=localStorage.getItem('waraqa-language')||'ar';
const excluded='.doc-info h3,.doc-info p,#doc-title,#doc-meta,#ocr-text,.folder-chips,textarea,script,style,[data-user-content]';
function translate(){document.documentElement.lang=language;document.documentElement.dir=language==='en'?'ltr':'rtl';const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.parentElement?.closest(excluded)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let node;while(node=walker.nextNode()){const trimmed=node.nodeValue.trim(),ar=reverse[trimmed]||trimmed,desired=language==='en'?(strings[ar]||trimmed):ar;if(trimmed&&desired!==trimmed)node.nodeValue=node.nodeValue.replace(trimmed,desired);}for(const element of document.querySelectorAll('[placeholder],[aria-label]'))for(const attribute of ['placeholder','aria-label']){const current=element.getAttribute(attribute);if(!current)continue;const ar=reverse[current]||current,desired=language==='en'?(strings[ar]||current):ar;if(desired!==current)element.setAttribute(attribute,desired);}}
export function setLanguage(value){language=value==='en'?'en':'ar';localStorage.setItem('waraqa-language',language);translate();}
export function initLanguage(){translate();new MutationObserver(translate).observe(document.body,{subtree:true,childList:true,characterData:true});}
